1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = { itemType: string; amount: number };
14	
15	export type ClaimStep = {
16	  op: "claim";
17	  policy: number;
18	  incident: { cause: string; damages: Damage[] };
19	};
20	
21	export type Step = QuoteStep | ClaimStep;
22	
23	export type Customer = { yearsWithMHPCO: number };
24	
25	export type Scenario = {
26	  customer: Customer;
27	  steps: Step[];
28	};
29	
30	export type ScenarioResults = {
31	  results: unknown[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
36	const LOYALTY_DISCOUNT = 0.2;
37	const LOYALTY_YEARS = 2;
38	const FOLLOW_UP_DISCOUNT = 0.15;
39	
40	const BASE_PREMIUMS: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	
49	const INSURANCE_VALUES: Record<string, number> = {
50	  sword: 1000,
51	  amulet: 600,
52	  staff: 800,
53	  potion: 400,
54	  rune: 250,
55	  moonstone: 250,
56	};
57	
58	const DEDUCTIBLE = 100;
59	const CAP_MULTIPLE = 2;
60	const HALF_REIMBURSEMENT_LEVEL = 8;
61	const HALF_REIMBURSEMENT = 0.5;
62	
63	const BLOCK_SIZE = 3;
64	const BLOCK_BASE_PREMIUM = 60;
65	
66	const COMPONENT_TYPES = ["rune", "moonstone"];
67	
68	/** Items are priced per type, because the component block applies to alike items. */
69	const groupByType = (items: Item[]): Map<string, Item[]> =>
70	  items.reduce(
71	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
72	    new Map<string, Item[]>(),
73	  );
74	
75	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
76	
77	/**
78	 * Item-level risk surcharges, each a rate on the item's own base premium.
79	 * They are separate addends: unlike the policy-level initial assessment, they
80	 * do not compound with each other or with it.
81	 */
82	const CURSE_SURCHARGE = 0.5;
83	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
84	const HIGH_ENCHANTMENT_LEVEL = 5;
85	
86	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
87	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
88	  {
89	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
90	    rate: HIGH_ENCHANTMENT_SURCHARGE,
91	  },
92	];
93	
94	const itemSurchargeTotal = (item: Item): number =>
95	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
96	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
97	    0,
98	  );
99	
100	/**
101	 * A building block of exactly 3 alike components is offered at a special base
102	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
103	 * runes are charged per item.
104	 */
105	const formsComponentBlock = (type: string, items: Item[]): boolean =>
106	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
107	
108	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
109	  formsComponentBlock(type, items)
110	    ? BLOCK_BASE_PREMIUM
111	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
112	
113	const policyBasePremium = (items: Item[]): number =>
114	  [...groupByType(items)].reduce(
115	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
116	    0,
117	  );
118	
119	/**
120	 * Money is always rounded in the MHPCO's favour. Which way that is depends on
121	 * the direction it flows: a premium is paid *to* the MHPCO, so it rounds up;
122	 * a payout is paid *by* it, so it rounds down (see `roundPayoutInMHPCOsFavour`).
123	 */
124	const roundPremiumInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
125	
126	/**
127	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
128	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
129	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
130	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
131	 */
132	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
133	
134	const policyItemSurchargeTotal = (items: Item[]): number =>
135	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
136	
137	/**
138	 * Policy-level modifiers, each a signed rate on the policy base premium.
139	 * Like the item-level surcharges they are independent addends: they do not
140	 * compound with one another. A discount is simply a negative rate.
141	 */
142	type Policy = { items: Item[] };
143	
144	type ScenarioState = {
145	  customer: Customer;
146	  contractsIssued: number;
147	  policies: Map<number, Policy>;
148	};
149	
150	const POLICY_MODIFIER_RULES: { applies: (state: ScenarioState) => boolean; rate: number }[] = [
151	  {
152	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
153	    rate: -LOYALTY_DISCOUNT,
154	  },
155	  { applies: ({ contractsIssued }) => contractsIssued > 0, rate: -FOLLOW_UP_DISCOUNT },
156	];
157	
158	const policyModifierTotal = (basePremium: number, state: ScenarioState): number =>
159	  POLICY_MODIFIER_RULES.filter(({ applies }) => applies(state)).reduce(
160	    (sum, { rate }) => sum + basePremium * rate,
161	    0,
162	  );
163	
164	/**
165	 * The premium is the policy base premium plus a set of independent addends,
166	 * each a rate on that same base — they do not compound with one another:
167	 *
168	 *   100 base + 50 curse + 30 high ench - 20 loyalty + 10 first insurance = 170, + 5 fee
169	 *
170	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
171	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
172	 * documented there.
173	 */
174	const quote = (step: QuoteStep, state: ScenarioState): { premium: number } => {
175	  const basePremium = policyBasePremium(step.items);
176	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
177	  const itemSurcharges = policyItemSurchargeTotal(step.items);
178	  const policyModifiers = policyModifierTotal(basePremium, state);
179	
180	  return {
181	    premium: roundPremiumInMHPCOsFavour(
182	      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
183	    ),
184	  };
185	};
186	
187	/** The payout half of the rule on `roundPremiumInMHPCOsFavour`: down. */
188	const roundPayoutInMHPCOsFavour = (payout: number): number => Math.floor(payout);
189	
190	const insuranceSum = (items: Item[]): number =>
191	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
192	
193	/**
194	 * Damage to a highly enchanted item is only half reimbursed. The clause applies
195	 * to the damage amount; the deductible is subtracted afterwards.
196	 */
197	const reimbursement = (item: Item, amount: number): number =>
198	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL ? amount * HALF_REIMBURSEMENT : amount;
199	
200	/** A deductible applies per damage event, i.e. once per damaged item. */
201	const damagePayout = (damage: Damage, policy: Policy): number => {
202	  const item = policy.items.find(({ type }) => type === damage.itemType) as Item;
203	
204	  return reimbursement(item, damage.amount) - DEDUCTIBLE;
205	};
206	
207	/**
208	 * A claim names the policy it is made against by the step index of the quote
209	 * that created it. That the policy exists is currently an *assumption*, not a
210	 * guarantee — a claim naming an unissued policy is a specified error case that
211	 * is not implemented yet, so this deliberately still fails on `undefined`.
212	 * The assumption is named here so that the missing check is visible rather
213	 * than buried in an `as` cast.
214	 */
215	const assumeIssued = (policy: Policy | undefined): Policy => policy as Policy;
216	
217	const claim = (
218	  step: ClaimStep,
219	  state: ScenarioState,
220	): { payout: number; remainingCap: number } => {
221	  const policy = assumeIssued(state.policies.get(step.policy));
222	  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
223	  const payout = roundPayoutInMHPCOsFavour(
224	    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policy), 0),
225	  );
226	
227	  return { payout, remainingCap: cap - payout };
228	};
229	
230	/**
231	 * Steps are processed in order and later steps depend on earlier ones — a quote
232	 * issues a contract that discounts every following quote, and a claim is made
233	 * against a policy an earlier quote created. Each step therefore maps its
234	 * incoming state to a result plus the state the next step sees.
235	 */
236	const runStep = (
237	  step: Step,
238	  state: ScenarioState,
239	  index: number,
240	): { result: unknown; nextState: ScenarioState } =>
241	  step.op === "quote"
242	    ? {
243	        result: quote(step, state),
244	        nextState: {
245	          ...state,
246	          contractsIssued: state.contractsIssued + 1,
247	          policies: new Map(state.policies).set(index, { items: step.items }),
248	        },
249	      }
250	    : { result: claim(step, state), nextState: state };
251	
252	export const runScenario = (scenario: Scenario): ScenarioResults => {
253	  const { results } = scenario.steps.reduce<{
254	    results: unknown[];
255	    state: ScenarioState;
256	  }>(
257	    ({ results, state }, step, index) => {
258	      const { result, nextState } = runStep(step, state, index);
259	
260	      return { results: [...results, result], state: nextState };
261	    },
262	    {
263	      results: [],
264	      state: { customer: scenario.customer, contractsIssued: 0, policies: new Map() },
265	    },
266	  );
267	
268	  return { results };
269	};
