/**
 * Damage to a highly enchanted item is only half reimbursed. The clause applies
 * to the damage amount; the deductible is subtracted afterwards.
 */
const reimbursement = (item: Item, amount: number): number =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL ? amount * HALF_REIMBURSEMENT : amount;

/** A deductible applies per damage event, i.e. once per damaged item. */
const damagePayout = (damage: Damage, policy: Policy): number => {
  const item = policy.items.find(({ type }) => type === damage.itemType) as Item;

  return reimbursement(item, damage.amount) - DEDUCTIBLE;
};

